process.env.NODE_TLS_REJECT_UNAUTHORIZED='0';
const WP='https://dev.avesa.lt';
const AUTH='Basic '+Buffer.from((process.env.WP_USER||'').trim()+':'+(process.env.WP_APP_PASS||'').trim()).toString('base64');
const GH=process.env.GH_TOKEN, REPO=process.env.GH_REPO;
const KAT='';
const DEP=Buffer.from('','base64').toString();
async function putRaw(path,b64,msg){
  const url=`https://api.github.com/repos/${REPO}/contents/${path}`;
  let sha; try{ const r=await fetch(url,{headers:{Authorization:`Bearer ${GH}`}}); if(r.ok) sha=(await r.json()).sha; }catch(e){}
  const body={message:msg||'uxs7', content:b64}; if(sha) body.sha=sha;
  const pr=await fetch(url,{method:'PUT',headers:{Authorization:`Bearer ${GH}`,'Content-Type':'application/json'},body:JSON.stringify(body)});
  return pr.status;
}
const putJson=(p,o)=>putRaw(p, Buffer.from(JSON.stringify(o,null,2)).toString('base64'),'uxs7 json');
async function snip(name,code){
  const r=await fetch(`${WP}/wp-json/code-snippets/v1/snippets`,{method:'POST',
    headers:{Authorization:AUTH,'Content-Type':'application/json'},
    body:JSON.stringify({name, code, scope:'global', active:true})});
  return await r.json();
}
async function off(id){ await fetch(`${WP}/wp-json/code-snippets/v1/snippets/${id}`,{method:'POST',
  headers:{Authorization:AUTH,'Content-Type':'application/json'},body:JSON.stringify({active:false})}); }
const pause=ms=>new Promise(x=>setTimeout(x,ms));
async function main(){
  const out={VERSIJA:'UXS7'};
  let r=await fetch(`${WP}/wp-json/code-snippets/v1/snippets`,{headers:{Authorization:AUTH}});
  const list=await r.json();
  for(const t of (Array.isArray(list)?list:[]).filter(s=>s.active&&/^TEMP/i.test(s.name||''))){ await off(t.id); }
  let s=await snip('TEMP uxs7 set kat', "update_option('ps_uxd_kat','"+KAT+"','no');");
  await pause(2000); await fetch(`${WP}/`,{headers:{Authorization:AUTH}}); await off(s.id);
  const sd=await snip('TEMP uxs7 deploy', DEP.replace(/^<\?php\s*/,''));
  await pause(2500);
  let resp=await fetch(`${WP}/?ps_uxd3=1&k=dq7m3z`,{headers:{Authorization:AUTH}});
  try{ out.deploy=JSON.parse(await resp.text()); }catch(e){ out.deploy_raw=(await resp.text()).slice(0,300); }

  const {chromium}=await import('playwright');
  const br=await chromium.launch();
  const ctx=await br.newContext({ignoreHTTPSErrors:true, viewport:{width:1680,height:1050}});
  const page=await ctx.newPage();
  const jsErr=[]; page.on('pageerror',e=>jsErr.push(String(e)));
  await page.goto(`${WP}/?ps_uxlog2=1&k=dq7m3z`,{waitUntil:'networkidle',timeout:60000});

  /* 1) APRASYMAI: ar apacia pasiekiama */
  await page.goto(`${WP}/wp-admin/admin.php?page=ps-katalogas&kruva=visos&q=EU221Y`,{waitUntil:'networkidle',timeout:60000});
  await pause(1200);
  const a=await page.$('.pskat-t tbody tr[data-id] a.atv');
  if(a){
    await a.click(); await pause(3500);
    await page.evaluate(()=>{ const b=document.querySelector('.kort-tabs button[data-t=apr]'); if(b) b.click(); });
    await pause(4500);
    out.aprasymai=await page.evaluate(()=>{
      const k=document.getElementById('pskat-kort');
      const p=document.querySelector('.kort-pane[data-p=apr]');
      return {kortele_aukstis:Math.round(k.getBoundingClientRect().height),
              clientHeight:k.clientHeight, scrollHeight:k.scrollHeight,
              galima_slinkti:k.scrollHeight>k.clientHeight,
              telpa_ekrane:k.getBoundingClientRect().bottom<=window.innerHeight+2,
              blokai:Array.prototype.map.call(p.querySelectorAll('.kort-antr'),x=>x.textContent.trim())};
    });
    /* nuslenkam i pati apacia — ar paskutinis blokas matomas */
    await page.evaluate(()=>{ const k=document.getElementById('pskat-kort'); k.scrollTop=k.scrollHeight; });
    await pause(800);
    out.apacia_matoma=await page.evaluate(()=>{
      const p=document.querySelector('.kort-pane[data-p=apr]');
      const bs=p.querySelectorAll('.kort-antr');
      const last=bs[bs.length-1];
      const r=last.getBoundingClientRect();
      return {paskutinis:last.textContent.trim(), top:Math.round(r.top), matomas:r.top>0&&r.top<window.innerHeight};
    });
    let png=await page.screenshot(); out.s_apr=await putRaw('screenshots/uxs7_aprasymai.png', png.toString('base64'),'uxs7 apr');

    /* 2) NUOTRAUKU mygtukai */
    await page.evaluate(()=>{ const b=document.querySelector('.kort-tabs button[data-t=fot]'); if(b) b.click(); });
    await pause(1200);
    out.foto_mygtukai=await page.evaluate(()=>
      Array.prototype.map.call(document.querySelectorAll('.kort-pane[data-p=fot] .kort-foto-myg button'),b=>b.textContent.trim()));
    png=await page.screenshot(); out.s_foto=await putRaw('screenshots/uxs7_nuotraukos.png', png.toString('base64'),'uxs7 foto');
  }

  /* 3) ATSTATYTA nuotrauka — vizualiai */
  await page.goto(`${WP}/wp-admin/admin.php?page=ps-katalogas&kruva=visos&q=DP-83724-6`,{waitUntil:'networkidle',timeout:60000});
  await pause(1500);
  out.atstatyta_sarase=await page.evaluate(()=>{
    const img=document.querySelector('.pskat-t tbody tr[data-id] img.mini');
    return img?img.getAttribute('src').split('/').pop():null;
  });
  let png=await page.screenshot({clip:{x:0,y:200,width:1680,height:400}});
  out.s_atstatyta=await putRaw('screenshots/uxs7_atstatyta.png', png.toString('base64'),'uxs7 atst');

  out.js_klaidos=jsErr.slice(0,8);
  await br.close(); await off(sd.id);
  r=await fetch(`${WP}/wp-json/code-snippets/v1/snippets`,{headers:{Authorization:AUTH}});
  const l2=await r.json();
  out.liko_temp=(Array.isArray(l2)?l2:[]).filter(x=>x.active&&/^TEMP/i.test(x.name||'')).map(x=>x.name);
  await putJson('analize/uxs7.json', out);
}
main().catch(async e=>{ await putJson('analize/uxs7.json',{klaida:String(e),stack:String(e&&e.stack).slice(0,700)}); });
